CREATE TABLE IF NOT EXISTS public.guarantors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id) ON DELETE CASCADE, name text NOT NULL, phone text, email text, national_id text, address text, employment_status text, employer_name text, relationship text, status text NOT NULL DEFAULT 'PENDING', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());